import { asString, useSearchParam } from '../../url/useSearchParam';

// The session lives in the URL: `user` is the signed-in name (no password), `sheet` the active
// sheet id. Every feature that works per sheet or records who did something reads these.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

export type Sheet = { id: string };
export const sheetKey = (id: string) => ['sheet', id] as const;
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { AppSession } from '../../slots/defs/appSession';
import { sheetKey, useCurrentSheet, useCurrentUser } from './session';
import type { Sheet } from './session';

function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [id, setId] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();

  const load = useMutation({
    mutationFn: (sheetId: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/load`, {}),
    onSuccess: async (loaded) => {
      queryClient.setQueryData(sheetKey(loaded.id), loaded);
      // Re-loading a sheet re-reads everything kept under it from the store.
      await queryClient.invalidateQueries({
        predicate: (q) => q.queryKey[0] === 'sheet' && q.queryKey[1] === loaded.id && q.queryKey.length > 2,
      });
      setSheet(loaded.id);
    },
    onError: () => setError('The sheet could not be loaded.'),
  });

  if (!user) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = id.trim();
    setError('');
    if (!trimmed) {
      setError('Type a sheet id to load.');
      return;
    }
    load.mutate(trimmed);
  };

  return (
    <form data-testid="sheet-form" onSubmit={submit}>
      <input
        data-testid="sheet-id-input"
        placeholder="Sheet id"
        value={id}
        onChange={(e) => {
          setId(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load
      </button>
      {error && <span data-testid="sheet-load-error">{error}</span>}
      {sheet && (
        <span>
          Sheet <strong data-testid="sheet-current-id">{sheet}</strong>
        </span>
      )}
    </form>
  );
}

export const contribution = AppSession.fill({ order: 10, Component: SheetPicker });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentUser } from './session';

function SignIn() {
  const [user, setUser] = useCurrentUser();
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) {
      setError('Type a name to sign in.');
      return;
    }
    setError('');
    setUser(trimmed);
  };

  if (user) {
    return (
      <span data-testid="signed-in">
        Signed in as <strong data-testid="current-user">{user}</strong>
      </span>
    );
  }
  return (
    <form data-testid="signin-form" onSubmit={submit}>
      <input
        data-testid="signin-name"
        placeholder="Your name"
        value={name}
        onChange={(e) => {
          setName(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="signin-submit">
        Sign in
      </button>
      {error && <span data-testid="signin-error">{error}</span>}
    </form>
  );
}

